<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';if(empty($_SESSION['admin_id'])){http_response_code(403);exit('Nicht angemeldet.');}
require_once dirname(__DIR__).'/private/system_check.php';require_once dirname(__DIR__).'/private/ui.php';
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();try{if(($_POST['action']??'')!=='run_tasks')throw new RuntimeException('Aktion ungültig.');require_once dirname(__DIR__).'/private/automation.php';$run=gszRunAutomation($pdo,$config);$_SESSION['app_notice']=$run['status']==='PASS'?'Aufgaben aktualisiert und neuer Wochenvorschlag vorbereitet. Keine Planänderung ungefragt übernommen.':'Hintergrundlauf nicht vollständig. Status prüfen.';}catch(Throwable $e){$_SESSION['app_error']='Hintergrundlauf nicht verfügbar. Migration/Serverkonfiguration prüfen.';}redirect('system_check.php');}
$result=gszSystemCheck($config,$pdo);gszPageStart('Systemstatus',$result['blocks']?$result['blocks'].' Punkte müssen behoben werden':'Alles Wesentliche in Ordnung');require_once dirname(__DIR__).'/private/automation.php';
$order=['block'=>0,'warn'=>1,'ok'=>2];$checks=$result['checks'];usort($checks,fn($a,$b)=>$order[$a['status']]<=>$order[$b['status']]);?>
<div class="rows"><?php foreach($checks as $c):?><div class="tenant"><span class="who"><?=e($c['label'])?></span><span class="pill <?=['ok'=>'ok','warn'=>'wait','block'=>'warn'][$c['status']]?>"><?=e(['ok'=>'OK','warn'=>'Hinweis','block'=>'Beheben'][$c['status']])?></span><span class="det"><?=e($c['detail'])?></span></div><?php endforeach?></div>
<h2 class="section-title">Hintergrundaufgaben</h2><div class="rows"><?php foreach(gszAutomationStatus($pdo,$config) as $s):?><div class="tenant"><span class="who"><?=e($s['label'])?></span><?php $unused=in_array($s['job_key'],['seo','stays'],true)&&!$s['last_success']&&!$s['last_started'];?><span class="pill <?=$unused?'wait':($s['status']==='PASS'?'ok':($s['status']==='BLOCKED'?'warn':'wait'))?>"><?=e($unused?'Nicht eingerichtet':(['PASS'=>'OK','BLOCKED'=>'Fehler','NOT TESTED'=>'Noch nie gelaufen','running'=>'Läuft'][$s['status']]??$s['status']))?></span><span class="det">Zuletzt erfolgreich: <?=e($s['last_success']?(new DateTimeImmutable($s['last_success'].' UTC'))->setTimezone(new DateTimeZone('Europe/Berlin'))->format('d.m.Y H:i'):'nie')?><?=$s['detail']!==''?' · '.e($s['detail']):($s['last_error_code']?' · Fehler '.e($s['last_error_code']):'')?></span></div><?php endforeach?></div>
<form method="post" style="margin-top:16px"><?php gszFields('run_tasks');?><button>Hintergrundaufgaben jetzt ausführen</button></form><p class="hint">Normalerweise nicht nötig: Die Zentrale erledigt das beim Öffnen von „Heute“ (stündlich) und „Mail“ (alle 5 Minuten) selbst.</p><?php gszPageEnd();
